    const pages = await buildSite({ contentDir: content, outputDir: output });

    expect(pages).toEqual(expect.arrayContaining([
      expect.objectContaining({ title: 'Hello World', date: '2026-08-13', tags: ['welcome'], slug: 'hello.html' }),
